//@ProcessingGroup("invoice")
@Component("invoice-projector")
public class InvoiceProjector extends InvoiceEntityProjector {
		
	// core constructor
	public InvoiceProjector(ProjectorRegistry registry,
									InvoiceRepository repository,
									QueryUpdateEmitter queryUpdateEmitter ) {
        super(registry, repository);
        this.queryUpdateEmitter = queryUpdateEmitter;
    }	

	/*
     * @param	event CreateInvoiceEvent
     */
    @EventHandler( payloadType=CreateInvoiceEvent.class )
    public void handle( CreateInvoiceEvent event) {
	    LOGGER.info("handling CreateInvoiceEvent - " + event );
	    Invoice entity = new Invoice();
            entity.setInvoiceId( event.getInvoiceId() );
            entity.setInvoiceNumber( event.getInvoiceNumber() );
            entity.setIssuedDate( event.getIssuedDate() );
            entity.setDueDate( event.getDueDate() );
            entity.setTotal( event.getTotal() );
            entity.setStatus( event.getStatus() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllInvoice( entity );
    }

    /*
     * @param	event UpdateInvoiceEvent
     */
    @EventHandler( payloadType=UpdateInvoiceEvent.class )
    public void handle( UpdateInvoiceEvent event) {
    	LOGGER.info("handling UpdateInvoiceEvent - " + event );
    	
	    Invoice entity = new Invoice();
            entity.setInvoiceId( event.getInvoiceId() );
            entity.setInvoiceNumber( event.getInvoiceNumber() );
            entity.setIssuedDate( event.getIssuedDate() );
            entity.setDueDate( event.getDueDate() );
            entity.setTotal( event.getTotal() );
            entity.setOrder( event.getOrder() );
            entity.setStatus( event.getStatus() );
 
    	// ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		update(entity);

    	// ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindInvoice( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllInvoice( entity );        
    }
    
    /*
     * @param	event DeleteInvoiceEvent
     */
    @EventHandler( payloadType=DeleteInvoiceEvent.class )
    public void handle( DeleteInvoiceEvent event) {
    	LOGGER.info("handling DeleteInvoiceEvent - " + event );
    	
    	// ------------------------------------------
    	// delete delegation
    	// ------------------------------------------
    	Invoice entity = delete( event.getInvoiceId() );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllInvoice( entity );

    }    

    /*
     * @param	event AssignOrderToInvoiceEvent
     */
    @EventHandler( payloadType=AssignOrderToInvoiceEvent.class)
    public void handle( AssignOrderToInvoiceEvent event) {
	    LOGGER.info("handling AssignOrderToInvoiceEvent - " + event );

	    // ------------------------------------------
	    // delegate to assignTo
	    // ------------------------------------------
	    Invoice entity = assignOrder( event.getInvoiceId(), event.getAssignment() );

	    // ------------------------------------------
    	// emit to subscribers that find one
    	// ------------------------------------------    	
        emitFindInvoice( entity );

    	// ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllInvoice( entity );
    }
    

	/*
	 * @param	event UnAssignOrderFromInvoiceEvent
	 */
	@EventHandler( payloadType=UnAssignOrderFromInvoiceEvent.class)
	public void handle( UnAssignOrderFromInvoiceEvent event) {
	    LOGGER.info("handling UnAssignOrderFromInvoiceEvent - " + event );

	    // ------------------------------------------
	    // delegate to unAssignFrom
	    // ------------------------------------------
	    Invoice entity = unAssignOrder( event.getInvoiceId() );

		// ------------------------------------------
		// emit to subscribers that find one
		// ------------------------------------------    	
	    emitFindInvoice( entity );
	
		// ------------------------------------------
		// emit to subscribers that find all
		// ------------------------------------------    	
	    emitFindAllInvoice( entity );
	}




    /**
     * Method to retrieve the Invoice via an InvoicePrimaryKey.
     * @param 	id Long
     * @return 	Invoice
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Invoice handle( FindInvoiceQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getInvoiceId() );
    }
    
    /**
     * Method to retrieve a collection of all Invoices
     *
     * @param	query	FindAllInvoiceQuery 
     * @return 	List<Invoice> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Invoice> handle( FindAllInvoiceQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindInvoice,
 * but only if the id matches
 *
 * @param		entity	Invoice
 */
	protected void emitFindInvoice( Invoice entity ) {
		LOGGER.info("handling emitFindInvoice" );
		
	    queryUpdateEmitter.emit(FindInvoiceQuery.class,
	                            query -> query.getFilter().getInvoiceId().equals(entity.getInvoiceId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllInvoice
	 * 
	 * @param		entity	Invoice
	 */
	protected void emitFindAllInvoice( Invoice entity ) {
		LOGGER.info("handling emitFindAllInvoice" );
		
	    queryUpdateEmitter.emit(FindAllInvoiceQuery.class,
	                            query -> true,
	                            entity);
	}

	//--------------------------------------------------
    // attributes
    // --------------------------------------------------
	@Autowired
	private final QueryUpdateEmitter queryUpdateEmitter;
    private static final Logger LOGGER 	= Logger.getLogger(InvoiceProjector.class.getName());

}
